-- Diplomados ampliados a 30 h o más (opción B), 02/10/2026. Consolidado e idempotente: se puede ejecutar completo en Supabase.
-- Actualiza horas y descripción de 15 diplomados y las horas de todas las rutas. No toca precios, inscripciones ni avances.
BEGIN;
UPDATE cursos SET horas=30, descripcion='Aprende a identificar peligros, evaluar riesgos y organizar la seguridad de tu centro de trabajo con las principales normas de la STPS: comisión de seguridad e higiene, equipo de protección personal, incendios, señalización, químicos, ergonomía, ruido, emergencias e investigación de accidentes. Incluye 20 casos de talleres, fábricas y comercios mexicanos con decisiones guiadas, 4 laboratorios de simulación y un proyecto final en el que armas el programa de seguridad de un centro de trabajo real, con matrices e indicadores en hoja de cálculo. Para supervisores, RH, EHS, comisiones y dueños de pymes. No sustituye la asesoría de un especialista.' WHERE id='d-seguridad-higiene';
UPDATE cursos SET horas=30, descripcion='Aprende a llevar las cuentas de tu negocio, leer tus números en hoja de cálculo, calcular tu ISR en el RESICO y tu IVA, y facturar bien en CFDI 4.0. Incluye 20 casos de negocios mexicanos (taquerías, estéticas, talleres, tiendas en línea) con decisiones guiadas, 4 laboratorios y un proyecto final en el que armas el tablero contable y fiscal de un negocio real. Es práctico y para personas físicas con negocios pequeños; no sustituye la asesoría de un contador público.' WHERE id='d-contabilidad-resico';
UPDATE cursos SET horas=30, descripcion='Para quienes «les tocó» un proyecto sin formación formal: abrir una sucursal, organizar un evento, lanzar una app o implementar un sistema. Aprende a definir alcance, armar cronograma y ruta crítica, presupuestar, manejar riesgos, trabajar con Scrum y Kanban, medir avance con valor ganado en hoja de cálculo y cerrar bien. Incluye 20 casos de proyectos reales en empresas mexicanas con decisiones guiadas, 4 laboratorios de simulación y un proyecto final en el que armas el plan completo de un proyecto tuyo. Te da bases para certificaciones como PMP o Scrum Master, que otorgan organismos externos y no este diplomado.' WHERE id='d-proyectos';
UPDATE cursos SET horas=30, descripcion='Arma la estrategia digital de tu negocio paso a paso: cliente ideal, WhatsApp Business y perfil de Google, contenido para redes, anuncios pagados y medición en hoja de cálculo. Incluye 20 casos de negocios mexicanos con decisiones guiadas, 4 laboratorios de simulación y un proyecto final en el que armas el plan de marketing digital de 90 días de un negocio real. Es práctico y con ejemplos mexicanos; no promete ventas garantizadas: te enseña a probar, medir y decidir con datos.' WHERE id='d-marketing-digital';
UPDATE cursos SET horas=30, descripcion='Prepárate para conseguir tu primer empleo de oficina o recepción, o para subir de puesto. Aprende a atender en persona y por teléfono, tomar recados completos, llevar agendas, redactar correos, minutas y oficios, archivar sin perder nada, manejar caja chica, viáticos e inventario en hoja de cálculo, revisar que una factura traiga bien los datos y usar herramientas de oficina e IA con responsabilidad. Incluye 20 casos de oficinas, consultorios y escuelas mexicanas con decisiones guiadas, 4 laboratorios de simulación y un proyecto final en el que armas tu manual de puesto y tu portafolio de documentos, además de plantillas de CV y carta de presentación.' WHERE id='d-asistente-administrativo';
UPDATE cursos SET horas=30, descripcion='Para supervisores, jefes de turno y coordinadores que acaban de subir de puesto: cómo dar instrucciones claras, retroalimentar, delegar, medir a tu equipo en Excel, manejar conflictos y cumplir tu papel en la NOM-035. Incluye 20 casos de fábricas, tiendas, hospitales y oficinas mexicanas con decisiones guiadas y ejercicios para aplicar con tu propio equipo, 4 laboratorios de simulación y un proyecto final en el que armas tu plan de liderazgo de 90 días. Práctico y con formatos listos; al terminar recibes una constancia de Instituto Mara.' WHERE id='d-liderazgo';
UPDATE cursos SET horas=30, descripcion='Para docentes de preescolar a secundaria, maestras sombra, orientadores, madres, padres y cuidadores. Aprende a reconocer señales de autismo (TEA), TDAH y dificultades específicas del aprendizaje, a adaptar el aula y la casa con apoyos basados en evidencia y a trabajar en equipo con la familia y los especialistas. Incluye 20 casos de aulas y familias mexicanas con decisiones guiadas y ejercicios para aplicar con alumnos reales, 4 laboratorios de simulación y un proyecto final en el que armas el plan de apoyo individual de un alumno. No capacita para diagnosticar: el diagnóstico lo hace un profesional de la salud.' WHERE id='d-neurodiversidad';
UPDATE cursos SET horas=30, descripcion='Para docentes, orientadores, madres, padres y personal que trabaja con niñas, niños y adolescentes. Aprende cómo se desarrollan las emociones, a reconocer señales de alerta (ansiedad, tristeza persistente, acoso, riesgos en línea), a escuchar y poner límites sin violencia, y a canalizar a tiempo con un plan y un directorio. Incluye 20 casos de escuelas y familias mexicanas con decisiones guiadas, 4 laboratorios de simulación y un proyecto final en el que armas el plan de bienestar y canalización de tu escuela, grupo o familia. No capacita para diagnosticar ni dar tratamiento: te prepara para detectar, acompañar y pedir la ayuda correcta.' WHERE id='d-infancia-adolescencia';
UPDATE cursos SET horas=32, descripcion='Da el paso de la TCC clásica al enfoque contextual: análisis funcional, formulación con la matriz ACT, los seis procesos de la terapia de aceptación y compromiso, las habilidades de la DBT, la activación conductual, la psicoterapia analítica funcional y el mindfulness con evidencia. Incluye 24 casos clínicos ficticios con decisiones guiadas, 5 laboratorios de simulación de sesión y un proyecto final en el que integras la formulación, el plan de intervención y la medición de un caso completo, con hojas de cálculo para medir el avance. Es para psicólogos con cédula, estudiantes avanzados de psicología y psicoterapeutas cognitivo-conductuales. Da fundamentos y técnicas; no sustituye la formación clínica supervisada ni las certificaciones de cada modelo, y no habilita para ejercer la psicoterapia.' WHERE id='d-terapias-contextuales';
UPDATE cursos SET horas=30, descripcion='Para psicólogos con cédula y estudiantes de los últimos semestres que no saben por dónde empezar cuando llega un paciente. Aprende a conducir la primera consulta, evaluar el estado mental y el riesgo, usar la CIE-11 y el DSM-5-TR con criterio, formular el caso con el modelo de las 5 P, medir resultados sesión a sesión y documentar bien tu expediente. Incluye 20 casos clínicos ficticios con decisiones guiadas, 4 laboratorios de simulación de consulta y un proyecto final en el que integras la evaluación completa de un caso, del encuadre al informe. No sustituye la supervisión clínica.' WHERE id='d-evaluacion-clinica';
UPDATE cursos SET horas=30, descripcion='Aprende a usar las ideas de Epicteto, Séneca y Marco Aurelio en tu vida diaria: distinguir lo que depende de ti, manejar la frustración, responder a críticas, poner límites y tomar mejores decisiones. Con lecturas de los textos originales explicadas con ejemplos cotidianos, 24 casos de la vida en México con decisiones guiadas, 5 laboratorios de práctica, un proyecto final y un cuaderno de práctica en PDF.' WHERE id='diplomado-estoicismo-vida-moderna';
UPDATE cursos SET horas=32, descripcion='Aprende a convencer sin manipular: escuchar lo que la otra persona necesita, argumentar con datos, manejar objeciones, escribir mensajes claros y presentar con confianza. Con ejemplos de «así no / así sí», frases listas para usar en ventas, trabajo en equipo y atención a clientes, 9 laboratorios de simulación con casos mexicanos, un proyecto final y un cuaderno de práctica en PDF.' WHERE id='diplomado-persuasion-etica';
UPDATE cursos SET horas=30, descripcion='Aprende a cumplir la NOM-035-STPS-2018 paso a paso: obligaciones según el tamaño del centro de trabajo, Guías de referencia I, II y III, calificación de cuestionarios en Excel, plan de acción y registros. Incluye 20 casos de empresas mexicanas con decisiones guiadas, 4 laboratorios y un proyecto final en el que armas el expediente NOM-035 de un centro de trabajo real. Incluye formatos listos para usar; no sustituye la lectura de la norma publicada en el DOF ni la asesoría legal o clínica.' WHERE id='d-nom035';
UPDATE cursos SET horas=30, descripcion='Aprende a contratar bien, calcular aguinaldo, vacaciones, horas extra y finiquitos en hoja de cálculo, cumplir con lo básico de la Ley Federal del Trabajo y desarrollar a tu equipo con indicadores claros. Incluye 20 casos de empresas mexicanas con cálculos verificados, 4 laboratorios y un proyecto final en el que armas el plan anual de RH de una empresa real. Pensado para auxiliares y generalistas de RH, dueños de pymes y administradores que llevan el personal; no sustituye la asesoría de un abogado laboral ni de un contador.' WHERE id='d-recursos-humanos';
UPDATE cursos SET horas=31, descripcion='Aprende a cuidar a una persona mayor con dignidad y seguridad: higiene, movilidad, prevención de caídas, alimentación, organización de medicamentos y señales de alarma. Incluye 20 casos de cuidado en casa con prácticas paso a paso, 7 laboratorios y un proyecto final en el que armas el plan de cuidado completo de una persona mayor. Pensado para familiares y personas que quieren trabajar como cuidadoras; no sustituye la atención médica ni de enfermería.' WHERE id='d-adulto-mayor';
